"""
Generated grid: recover_deferred_processing_failure. Cross-verified cell by cell at emit time.

Failure-Class: FC-finalization-transaction-attempts-replay-one-retired-id-five-times

Each test re-drives its cell through the real lane boundary
(``tests.unit.bounded_lane_grid_harness.drive_cell``) and compares the full
observable freeze against the literal the emit-time cross-verify produced;
the independent model walk and the emitter live outside the tree. Do not edit
frozen literals by hand.
"""

from tests.unit.bounded_lane_grid_harness import drive_cell

_LANE_LABEL = 'recover_deferred_processing_failure'
_LANE_LOGGER_NAME = 'database.conversation_finalization_jobs'


def _drive(monkeypatch, caplog, **params):
    return drive_cell(
        monkeypatch,
        caplog,
        label=_LANE_LABEL,
        lane_logger_name=_LANE_LOGGER_NAME,
        **params,
    )


def test_a0e0m1dnonetokfbare(monkeypatch, caplog) -> None:
    assert _drive(
        monkeypatch,
        caplog,
        aborts=0,
        expiries=0,
        max_attempts=1,
        deadline_mode='none',
        terminal='ok',
        abort_form='bare',
    ) == {
        'result': 'lane_ok',
        'raised': None,
        'reason': None,
        'retry_after': None,
        'cause': None,
        'body_calls': [
            1,
        ],
        'transactions': [
            'txn-1',
        ],
        'max_attempts_kwargs': [
            1,
        ],
        'sleeps': [],
        'engine_records': [],
        'lane_records': [],
    }


